public final class METGUPRetailPricingDataManager extends GUPRetailPricingDataManager { private METGUPOfferTmp validOfferDiscount, validOfferAdjustment; private METGUPOrderAttributeValueTmp orderAttributeValueHeader, orderAttributeValueLine;
#LOCALMACRO.ExistsConditionValueMatchOrderLineAttributes exists join ruleConditionLine where ruleConditionLine.RuleId == periodicDiscountLine.LinePricingRule exists join orderAttributeValueLine where orderAttributeValueLine.AttributeLink == ruleConditionLine.ConditionAttribute && ruleConditionLine.ConditionValue != '' && !(ruleConditionLine.ConditionValue like '*!*') && ruleConditionLine.ConditionValue like '%' + orderAttributeValueLine.AttributeValue + '%' #ENDMACRO
#LOCALMACRO.ExistsConditionValueContainsExcluding exists join ruleConditionLine where ruleConditionLine.RuleId == periodicDiscountLine.LinePricingRule && ruleConditionLine.ConditionValue like '*!*' #ENDMACRO
#LOCALMACRO.ExistsConditionValueAreAllEmpty notexists join ruleConditionLine where ruleConditionLine.RuleId == periodicDiscountLine.LinePricingRule && ruleConditionLine.ConditionValue != '' #ENDMACRO
}

