public METGUPOrderAttributeValueTmp parmOrderAttributeValueHeader(METGUPOrderAttributeValueTmp _orderAttributeValueTmp = orderAttributeValueHeader)
{
    orderAttributeValueHeader = _orderAttributeValueTmp;
    return orderAttributeValueHeader;
}

public METGUPOrderAttributeValueTmp parmOrderAttributeValueLine(METGUPOrderAttributeValueTmp _orderAttributeValueTmp = orderAttributeValueLine)
{
    orderAttributeValueLine = _orderAttributeValueTmp;
    return orderAttributeValueLine;
}

    protected void readRetailPriceAdjustments(
        CLRObject _priceDataList,
        ValidFromDate _minToDate,
        ValidFromDate _maxFromDate,
        Map _validationPeriodLookup)
    {
        RetailDiscountOffer periodicDiscount;
        RetailPeriodicDiscountLine periodicDiscountLine;
        UnitOfMeasure unitOfMeasure;
        InventDim inventDim;
        GUPTierPriceAdjustmentLine tierPriceAdjustmentLine;
        GUPPRICINGRULECONDITION ruleConditionLine;
        GUPPriceComponentCodeSetup marginComponentSetup;
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

        Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustment crtPriceAdjustment;

        // Lookup of promotion discount offer Ids to determine whether the offer Id has already been added to RetailTempOrderData.
        Set promoOfferIdSet = new Set(Types::String);
        GUPPriceTreeName priceTreeName = this.unifiedPricingParameter.PriceTreeName;

        void convert2CrtAdjustment()
        {
            crtPriceAdjustment = this.ConvertToPriceAdjustmentV2(periodicDiscount, periodicDiscountLine, '', periodicDiscountLine.InventDimId, unitOfMeasure);
            if (periodicDiscount.IsTierConfigurationEnabled == NoYes::Yes)
            {
                if (periodicDiscount.TierPriceAdjustmentMethod == GUPPriceTermCalculateMethod::Percent)
                {
                    crtPriceAdjustment.DiscountMethod = enum2int(RetailDiscountOfferLineDiscMethodBase::PercentOff);
                }
                else
                {
                    crtPriceAdjustment.DiscountMethod = enum2int(RetailDiscountOfferLineDiscMethodBase::AmountOff);
                }

                while select QtyLowest, PriceDiscPct from tierPriceAdjustmentLine
                    where tierPriceAdjustmentLine.OfferId == periodicDiscount.OfferId
                {
                    this.addCrtPriceAdjustmentTierForPriceAdjustment_NeedsToBeRevised(crtPriceAdjustment, tierPriceAdjustmentLine);
                }
            }
            crtPriceAdjustment.DiscountAmount = (-crtPriceAdjustment.DiscountAmount);
            crtPriceAdjustment.DiscountPercent = (-crtPriceAdjustment.DiscountPercent);
            crtPriceAdjustment.CanCompoundOnAdjustedPrice = marginComponentSetup.CompoundcalculationBasis;
            crtPriceAdjustment.CanApplyWithUnitConversion = periodicDiscountLine.UnitAppliesToAll;

            crtPriceAdjustment.ValidationPeriod = this.setCrtValidationPeriod(periodicDiscount, _validationPeriodLookup);
            crtPriceAdjustment.Dimension = GUPRetailPricingDataManager::ConvertToCrtInventoryDimension(inventDim);

            this.setCrtPricingRuleAndPriorityForPriceAdjustmentWithCache_NeedsToBeRevised(
                crtPriceAdjustment, groupCombination.Priority,
                periodicDiscount.HeaderPricingRule, periodicDiscountLine.LinePricingRule,
                null);

            _priceDataList.Add(crtPriceAdjustment);

            this.addOfferIdToTmpOrderDataList(periodicDiscount.OfferId, promoOfferIdSet);
        }

        #localmacro.WhileSelectPriceAdjustment
        while select forceliterals CompoundcalculationBasis from marginComponentSetup
            order by marginComponentSetup.CalculationSequence
            join periodicDiscount
            where marginComponentSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName
               && marginComponentSetup.PricingTreeName == priceTreeName
            join periodicDiscountLine
                where periodicDiscount.OfferId == periodicDiscountLine.OfferId
            join Priority from groupCombination
                where groupCombination.RecId == periodicDiscountLine.PriceAttributeGroupCombinationRecId
            join inventDim
                where inventDim.inventDimId == periodicDiscountLine.InventDimId
            outer join Symbol from unitOfMeasure
                where unitOfMeasure.RecId == periodicDiscountLine.UnitOfMeasure
            exists join validOfferAdjustment
                where validOfferAdjustment.OfferId == periodicDiscount.OfferId
        #endmacro

        delete_from mTmpOrderData;

        this.initializeValidOfferAdjustmentFromHeader(_maxFromDate, _minToDate);

        #WhileSelectPriceAdjustment
            #ExistsConditionValueMatchOrderLineAttributes
        {
            convert2CrtAdjustment();
        }

        #WhileSelectPriceAdjustment
            #ExistsConditionValueContainsExcluding
        {
            convert2CrtAdjustment();
        }

        #WhileSelectPriceAdjustment
            #ExistsConditionValueAreAllEmpty
        {
            convert2CrtAdjustment();
        }

        tmpOrderDataInsertList.insertDatabase();
    }

    protected void readRetailPeriodicDiscounts(
        CLRObject _priceDataList,
        ValidFromDate _minToDate,
        ValidFromDate _maxFromDate,
        Map _validationPeriodLookup)
    {
        GUPPriceComponentCode priceComponentCode;
        GUPPriceComponentCodeSetup priceComponentCodeSetup;
        RetailPeriodicDiscount periodicDiscount;
        RetailPeriodicDiscountLine periodicDiscountLine;
        UnitOfMeasure unitOfMeasure;
        InventDim inventDim;
        GUPPRICINGRULECONDITION ruleConditionLine;
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

        int discountType = 0;

        Microsoft.Dynamics.Commerce.Runtime.DataModel.PeriodicDiscount crtDiscount;
        Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingComponentCode crtPricingComponentCode;
        GUPPriceTreeName priceTreeName = this.unifiedPricingParameter.PriceTreeName;

        // Key = discount offer id, value = list of excluded price component code groups.
        Map discountExclusionMap = this.createDiscountExclusionMap_NeedsToBeRevised(_minToDate, _maxFromDate, priceTreeName);

        void convert2CrtDiscount()
        {
            crtDiscount = this.ConvertToCrtPeriodicDiscountV2(periodicDiscount, periodicDiscountLine, unitOfMeasure, discountType, '', periodicDiscountLine.InventDimId);

            crtPricingComponentCode = this.ConvertToCrtPricingComponentCode(priceComponentCodeSetup, priceComponentCode);
            crtDiscount.PricingComponentCode = crtPricingComponentCode;
            crtDiscount.PricingPriorityNumber = 1000 - crtPricingComponentCode.CalculationSequence;

            this.fillDiscountExclusionSet_NeedsToBeRevised(crtDiscount, periodicDiscount, discountExclusionMap);

            crtDiscount.ValidationPeriod = this.setCrtValidationPeriod(periodicDiscount, _validationPeriodLookup);
            crtDiscount.Dimension = GUPRetailPricingDataManager::ConvertToCrtInventoryDimension(inventDim);

            this.setCrtPricingRuleAndPriorityForDiscountWithCache(
                crtDiscount, groupCombination.Priority,
                periodicDiscount.HeaderPricingRule, periodicDiscountLine.LinePricingRule,
                null);

            _priceDataList.Add(crtDiscount);

            this.addOfferIdToTmpOrderDataList(periodicDiscount.OfferId, offerIdSet);
        }
        
        #localmacro.WhileSelectPriceDiscount
        while select forceliterals PriceComponentCodeName, CalculationSequence, CompoundCalculationBasis, ConcurrencyModeAcrossPriority from priceComponentCodeSetup
            order by priceComponentCodeSetup.CalculationSequence
            join periodicDiscount
            where priceComponentCodeSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName
               && priceComponentCodeSetup.PricingTreeName == priceTreeName
            join PriceComponentCodeGroup from priceComponentCode
                where priceComponentCodeSetup.PriceComponentCodeName == priceComponentCode.Name
            join periodicDiscountLine
                where periodicDiscount.OfferId == periodicDiscountLine.OfferId
            join Priority from groupCombination
                where groupCombination.RecId == periodicDiscountLine.PriceAttributeGroupCombinationRecId
            join inventDim
                where inventDim.inventDimId == periodicDiscountLine.InventDimId
            outer join Symbol from unitOfMeasure
                where unitOfMeasure.RecId == periodicDiscountLine.UnitOfMeasure
            exists join mTmpOrderItem
                where (mTmpOrderItem.UnitOfMeasure == periodicDiscountLine.UnitOfMeasure || periodicDiscountLine.UnitOfMeasure == 0)
            exists join validOfferDiscount
                where validOfferDiscount.OfferId == periodicDiscount.OfferId
        #endmacro

        delete_from mTmpOrderData;

        this.initializeValidOfferDiscountFromHeader(_maxFromDate, _minToDate);

        #WhileSelectPriceDiscount
            #ExistsConditionValueMatchOrderLineAttributes
        {
            convert2CrtDiscount();
        }

        #WhileSelectPriceDiscount
            #ExistsConditionValueContainsExcluding
        {
            convert2CrtDiscount();
        }

        #WhileSelectPriceDiscount
            #ExistsConditionValueAreAllEmpty
        {
            convert2CrtDiscount();
        }

        tmpOrderDataInsertList.insertDatabase();
    }

    private void initializeValidOfferDiscountFromHeader(ValidFromDate _maxFromDate, ValidFromDate _minToDate)
    {
        RetailPeriodicDiscount periodicDiscount;
        GUPPRICINGRULECONDITION ruleConditionHeader;

        select firstonly RecId from validOfferDiscount;
        if (!validOfferDiscount)
        {
            insert_recordset validOfferDiscount(OfferId)
                select forceliterals OfferId from periodicDiscount
                    where periodicDiscount.IsGupDiscount == NoYes::Yes
                       && periodicDiscount.PriceComponentType == GUPPriceComponent::RetailDiscounts
                       && periodicDiscount.Status in containerForStatus
                       && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Promotion
                       && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Shipping
                       && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::FreeItem
                       && ((periodicDiscount.ValidFrom <= _maxFromDate || periodicDiscount.ValidFrom <= noDate) &&
                           (periodicDiscount.ValidTo >= _minToDate || periodicDiscount.ValidTo <= noDate))
                    notexists join ruleConditionHeader
                        where ruleConditionHeader.RuleId == periodicDiscount.HeaderPricingRule
                        exists join orderAttributeValueHeader
                            where orderAttributeValueHeader.AttributeLink == ruleConditionHeader.ConditionAttribute
                               && ruleConditionHeader.ConditionValue != ''
                               && !(ruleConditionHeader.ConditionValue like '*!*')
                               && (!(ruleConditionHeader.ConditionValue like '%' + orderAttributeValueHeader.AttributeValue + '%')
                                || orderAttributeValueHeader.AttributeValue == '');
        }
    }

    private void initializeValidOfferAdjustmentFromHeader(ValidFromDate _maxFromDate, ValidFromDate _minToDate)
    {
        RetailPeriodicDiscount periodicDiscount;
        GUPPRICINGRULECONDITION ruleConditionHeader;

        select firstonly RecId from validOfferAdjustment;
        if (!validOfferAdjustment)
        {
            insert_recordset validOfferAdjustment(OfferId)
                select forceliterals OfferId from periodicDiscount
                    where periodicDiscount.IsGupDiscount == NoYes::Yes
                       && periodicDiscount.PriceComponentType == GUPPriceComponent::PriceMarginComponentAdjustment
                       && periodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::Promotion
                       && periodicDiscount.Status in containerForStatus
                       && ((periodicDiscount.ValidFrom <= _maxFromDate || periodicDiscount.ValidFrom <= noDate) &&
                           (periodicDiscount.ValidTo >= _minToDate || periodicDiscount.ValidTo <= noDate))
                    notexists join ruleConditionHeader
                        where ruleConditionHeader.RuleId == periodicDiscount.HeaderPricingRule
                        exists join orderAttributeValueHeader
                            where orderAttributeValueHeader.AttributeLink == ruleConditionHeader.ConditionAttribute
                               && ruleConditionHeader.ConditionValue != ''
                               && !(ruleConditionHeader.ConditionValue like '*!*')
                               && (!(ruleConditionHeader.ConditionValue like '%' + orderAttributeValueHeader.AttributeValue + '%')
                                || orderAttributeValueHeader.AttributeValue == '');
        }
    }

    protected void setCrtPricingRuleAndPriorityForDiscountWithCache(
        Microsoft.Dynamics.Commerce.Runtime.DataModel.PeriodicDiscount _priceDataList,
        int _priority,
        GUPRefRecId _pricingRuleHeader,
        GUPRefRecId _pricingRuleLine,
        GUPRetailPricingDataManagerPricingRuleCache _dbCache)
    {
        _priceDataList.PricingPriority = _priority;
        var ruleCollc = _priceDataList.PricingMatchingRules;

        // Load rules from cache.
        ruleCollc.add(GUPRetailPricingDataManager::ConvertToCrtPricingRule(_pricingRuleHeader));
        ruleCollc.add(GUPRetailPricingDataManager::ConvertToCrtPricingRule(_pricingRuleLine));
    }

    /// <summary>
    /// This method should be deleted once the same method access modifier of parent class is changed to protected
    /// </summary>
    private void setCrtPricingRuleAndPriorityForPriceAdjustmentWithCache_NeedsToBeRevised(
        Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustment _priceDataList,
        int _priority,
        GUPRefRecId _pricingRuleHeader,
        GUPRefRecId _pricingRuleLine,
        GUPRetailPricingDataManagerPricingRuleCache _dbCache)
    {
        _priceDataList.PricingPriority = _priority;
        var ruleCollc = _priceDataList.PricingMatchingRules;

        // Load rules from cache.
        ruleCollc.add(GUPRetailPricingDataManager::ConvertToCrtPricingRule(_pricingRuleHeader));
        ruleCollc.add(GUPRetailPricingDataManager::ConvertToCrtPricingRule(_pricingRuleLine));
    }

/// <summary>
/// This method should be deleted once the same method access modifier of parent class is changed to protected
/// </summary>
private void addCrtPriceAdjustmentTierForPriceAdjustment_NeedsToBeRevised(
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustment _priceDataList,
    GUPTierPriceAdjustmentLine _tierPriceAdjustmentLine)
{
    var tierCollc = _priceDataList.PriceAdjustmentTiers;
    tierCollc.Add(METGUPRetailPricingDataManager::ConvertToPriceAdjustmentTier_NeedsToBeRevised(_tierPriceAdjustmentLine));
}

    /// <summary>
    /// This method should be deleted once the same method access modifier of parent class is changed to protected
    /// </summary>
    private static Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustmentTier ConvertToPriceAdjustmentTier_NeedsToBeRevised(GUPTierPriceAdjustmentLine _tierPriceAdjustmentLine)
    {
        Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustmentTier crtTier = new Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustmentTier();

        crtTier.QuantityThreshold = _tierPriceAdjustmentLine.QtyLowest;
        crtTier.DiscountValue = -_tierPriceAdjustmentLine.PriceDiscPct;

        return crtTier;
    }

    /// <summary>
    /// This method should be deleted once the same method access modifier of parent class is changed to protected
    /// </summary>
    private Map createDiscountExclusionMap_NeedsToBeRevised(ValidFromDate _minToDate, ValidFromDate _maxFromDate, GUPPriceTreeName _priceTreeName)
    {
        GUPDiscountPriceComponentGroupExclusionList discountPriceComponentGroupExclusionList;
        GUPPriceComponentCodeSetup priceComponentCodeSetup;
        RetailPeriodicDiscount periodicDiscount;

        Map exclusionListMap = new Map(Types::String, Types::AnyType);

        while select discountPriceComponentGroupExclusionList
            where discountPriceComponentGroupExclusionList.IsExcluded == NoYes::Yes
            exists join periodicDiscount
                where periodicDiscount.OfferId == discountPriceComponentGroupExclusionList.OfferId
                   && periodicDiscount.Status in containerForStatus
                   && periodicDiscount.IsGupDiscount == NoYes::Yes
                   && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Promotion
                   && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Shipping
                   && ((periodicDiscount.ValidFrom <= _maxFromDate || periodicDiscount.ValidFrom <= noDate) &&
                      (periodicDiscount.ValidTo >= _minToDate || periodicDiscount.ValidTo <= noDate))
            exists join PriceComponentCodeName, PricingTreeName from priceComponentCodeSetup
                where priceComponentCodeSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName
                   && priceComponentCodeSetup.PricingTreeName == _priceTreeName
        {
            if (!exclusionListMap.exists(discountPriceComponentGroupExclusionList.OfferId))
            {
                exclusionListMap.add(discountPriceComponentGroupExclusionList.OfferId, new List(Types::String));
            }
            List exclusionList = exclusionListMap.lookup(discountPriceComponentGroupExclusionList.OfferId);
            exclusionList.addEnd(discountPriceComponentGroupExclusionList.PriceComponentCodeGroup);
        }

        return exclusionListMap;
    }

    /// <summary>
    /// This method should be deleted once the same method access modifier of parent class is changed to protected
    /// </summary>
    private void fillDiscountExclusionSet_NeedsToBeRevised(Microsoft.Dynamics.Commerce.Runtime.DataModel.PeriodicDiscount _crtDiscount,
        RetailPeriodicDiscount _periodicDiscount, Map _discountExclusionMap)
    {
        if (_discountExclusionMap.exists(_periodicDiscount.OfferId))
        {
            List exclusionList = _discountExclusionMap.lookup(_periodicDiscount.OfferId);
            ListEnumerator listEnum = exclusionList.getEnumerator();
            var groupExclusionSet = _crtDiscount.DiscountGroupExclusionSet;

            while (listEnum.moveNext())
            {
                groupExclusionSet.Add(listEnum.current());
            }
        }
    }
